  4511  static void
  4512  xmlCharacters(xmlParserCtxtPtr ctxt, const xmlChar *buf, int size,
  4513                int isBlank) {
  4514      int checkBlanks;
  4515
  4516      if ((ctxt->sax == NULL) || (ctxt->disableSAX))
  4517          return;
  4518
  4519      checkBlanks = (!ctxt->keepBlanks) ||
  4520                    (ctxt->sax->ignorableWhitespace != ctxt->sax->characters);
  4521
  4522      /*
  4523       * Calling areBlanks with only parts of a text node
  4524       * is fundamentally broken, making the NOBLANKS option
  4525       * essentially unusable.
  4526       */
  4527      if ((checkBlanks) &&
  4528          (areBlanks(ctxt, buf, size, isBlank))) {
  4529          if ((ctxt->sax->ignorableWhitespace != NULL) &&
  4530              (ctxt->keepBlanks))
  4531              ctxt->sax->ignorableWhitespace(ctxt->userData, buf, size);
  4532      } else {
  4533          if (ctxt->sax->characters != NULL)
  4534              ctxt->sax->characters(ctxt->userData, buf, size);
  4535
  4536          /*
  4537           * The old code used to update this value for "complex" data
  4538           * even if checkBlanks was false. This was probably a bug.
  4539           */
  4540          if ((checkBlanks) && (*ctxt->space == -1))
  4541              *ctxt->space = -2;
  4542      }
  4543  }
