  4545  /**
  4546   * Parse character data. Always makes progress if the first char isn't
  4547   * '<' or '&'.
  4548   *
  4549   * The right angle bracket (>) may be represented using the string "&gt;",
  4550   * and must, for compatibility, be escaped using "&gt;" or a character
  4551   * reference when it appears in the string "]]>" in content, when that
  4552   * string is not marking the end of a CDATA section.
  4553   *
  4554   *     [14] CharData ::= [^<&]* - ([^<&]* ']]>' [^<&]*)
  4555   * @param ctxt  an XML parser context
  4556   * @param partial  buffer may contain partial UTF-8 sequences
  4557   */
  4558  static void
  4559  xmlParseCharDataInternal(xmlParserCtxtPtr ctxt, int partial) {
  4560      const xmlChar *in;
  4561      int line = ctxt->input->line;
  4562      int col = ctxt->input->col;
  4563      int ccol;
  4564
  4565      GROW;
  4566      /*
  4567       * Accelerated common case where input don't need to be
  4568       * modified before passing it to the handler.
  4569       */
  4570      in = ctxt->input->cur;
  4571      do {
  4572  get_more_space:
  4573          while (*in == 0x20) { in++; ctxt->input->col++; }
  4574          if (*in == 0xA) {
  4575              do {
  4576                  ctxt->input->line++; ctxt->input->col = 1;
  4577                  in++;
  4578              } while (*in == 0xA);
  4579              goto get_more_space;
  4580          }
  4581          if (*in == '<') {
  4582              while (in > ctxt->input->cur) {
  4583                  const xmlChar *tmp = ctxt->input->cur;
  4584                  size_t nbchar = in - tmp;
  4585
  4586                  if (nbchar > XML_MAX_ITEMS)
  4587                      nbchar = XML_MAX_ITEMS;
  4588                  ctxt->input->cur += nbchar;
  4589
  4590                  xmlCharacters(ctxt, tmp, nbchar, 1);
  4591              }
  4592              return;
  4593          }
  4594
  4595  get_more:
  4596          ccol = ctxt->input->col;
  4597          while (test_char_data[*in]) {
  4598              in++;
  4599              ccol++;
  4600          }
  4601          ctxt->input->col = ccol;
  4602          if (*in == 0xA) {
  4603              do {
  4604                  ctxt->input->line++; ctxt->input->col = 1;
  4605                  in++;
  4606              } while (*in == 0xA);
  4607              goto get_more;
  4608          }
  4609          if (*in == ']') {
  4610              if ((in[1] == ']') && (in[2] == '>')) {
  4611                  xmlFatalErr(ctxt, XML_ERR_MISPLACED_CDATA_END, NULL);
  4612                  ctxt->input->cur = in + 1;
  4613                  return;
  4614              }
  4615              if ((!partial) || (ctxt->input->end - in >= 2)) {
  4616                  in++;
  4617                  ctxt->input->col++;
  4618                  goto get_more;
  4619              }
  4620          }
  4621          while (in > ctxt->input->cur) {
  4622              const xmlChar *tmp = ctxt->input->cur;
  4623              size_t nbchar = in - tmp;
  4624
  4625              if (nbchar > XML_MAX_ITEMS)
  4626                  nbchar = XML_MAX_ITEMS;
  4627              ctxt->input->cur += nbchar;
  4628
  4629              xmlCharacters(ctxt, tmp, nbchar, 0);
  4630
  4631              line = ctxt->input->line;
  4632              col = ctxt->input->col;
  4633          }
  4634          ctxt->input->cur = in;
  4635          if (*in == 0xD) {
  4636              in++;
  4637              if (*in == 0xA) {
  4638                  ctxt->input->cur = in;
  4639                  in++;
  4640                  ctxt->input->line++; ctxt->input->col = 1;
  4641                  continue; /* while */
  4642              }
  4643              in--;
  4644          }
  4645          if (*in == '<') {
  4646              return;
  4647          }
  4648          if (*in == '&') {
  4649              return;
  4650          }
  4651          if ((partial) && (*in == ']') && (ctxt->input->end - in < 2)) {
  4652              return;
  4653          }
  4654          SHRINK;
  4655          GROW;
  4656          in = ctxt->input->cur;
  4657      } while (((*in >= 0x20) && (*in <= 0x7F)) ||
  4658               (*in == 0x09) || (*in == 0x0a));
  4659      ctxt->input->line = line;
  4660      ctxt->input->col = col;
  4661      xmlParseCharDataComplex(ctxt, partial);
  4662  }
