  4664  /**
  4665   * Always makes progress if the first char isn't '<' or '&'.
  4666   *
  4667   * parse a CharData section.this is the fallback function
  4668   * of #xmlParseCharData when the parsing requires handling
  4669   * of non-ASCII characters.
  4670   *
  4671   * @param ctxt  an XML parser context
  4672   * @param partial  whether the input can end with truncated UTF-8
  4673   */
  4674  static void
  4675  xmlParseCharDataComplex(xmlParserCtxtPtr ctxt, int partial) {
  4676      xmlChar buf[XML_PARSER_BIG_BUFFER_SIZE + 5];
  4677      int nbchar = 0;
  4678      int cur, l;
  4679
  4680      cur = xmlCurrentCharRecover(ctxt, &l);
  4681      while ((cur != '<') && /* checked */
  4682             (cur != '&') &&
  4683             ((!partial) || (cur != ']') ||
  4684              (ctxt->input->end - ctxt->input->cur >= 2)) &&
  4685             (IS_CHAR(cur))) {
  4686          if ((cur == ']') && (NXT(1) == ']') && (NXT(2) == '>')) {
  4687              xmlFatalErr(ctxt, XML_ERR_MISPLACED_CDATA_END, NULL);
  4688          }
  4689          COPY_BUF(buf, nbchar, cur);
  4690          /* move current position before possible calling of ctxt->sax->characters */
  4691          NEXTL(l);
  4692          if (nbchar >= XML_PARSER_BIG_BUFFER_SIZE) {
  4693              buf[nbchar] = 0;
  4694
  4695              xmlCharacters(ctxt, buf, nbchar, 0);
  4696              nbchar = 0;
  4697              SHRINK;
  4698          }
  4699          cur = xmlCurrentCharRecover(ctxt, &l);
  4700      }
  4701      if (nbchar != 0) {
  4702          buf[nbchar] = 0;
  4703
  4704          xmlCharacters(ctxt, buf, nbchar, 0);
  4705      }
  4706      /*
  4707       * cur == 0 can mean
  4708       *
  4709       * - End of buffer.
  4710       * - An actual 0 character.
  4711       * - An incomplete UTF-8 sequence. This is allowed if partial is set.
  4712       */
  4713      if (ctxt->input->cur < ctxt->input->end) {
  4714          if ((cur == 0) && (CUR != 0)) {
  4715              if (partial == 0) {
  4716                  xmlFatalErrMsgInt(ctxt, XML_ERR_INVALID_CHAR,
  4717                          "Incomplete UTF-8 sequence starting with %02X\n", CUR);
  4718                  NEXTL(1);
  4719              }
  4720          } else if ((cur != '<') && (cur != '&') && (cur != ']')) {
  4721              /* Generate the error and skip the offending character */
  4722              xmlFatalErrMsgInt(ctxt, XML_ERR_INVALID_CHAR,
  4723                                "PCDATA invalid Char value %d\n", cur);
  4724              NEXTL(l);
  4725          }
  4726      }
  4727  }
